  let balance = 0;
  for (let i = 0; i < brackets.length; i++) {
    const char = brackets[i];
    if (char === '(') {
      balance++;
    } else if (char === ')') {
      balance--;
      if (balance < 0) {
        return false;
      }
    }
  }
  return balance === 0;
};

