const circularShift = (x, shift) => {
  const str = x.toString();
  const len = str.length;
  if (shift > len) {
    return str.split('').reverse().join('');
  }
  const effectiveShift = shift % len;
  if (effectiveShift === 0) {
    return str;
  }
  return str.slice(-effectiveShift) + str.slice(0, len - effectiveShift);
};

