  let minEven = Infinity;
  let minIndex = -1;

  for (let i = 0; i < arr.length; i++) {
    const value = arr[i];
    if (value % 2 === 0) {
      if (value < minEven) {
        minEven = value;
        minIndex = i;
      }
    }
  }

  if (minIndex === -1) {
    return [];
  }

  return [minEven, minIndex];
};

