    if (n < 2) return false;
    if (n === 2) return true;
    if (n % 2 === 0) return false;
    for (let i = 3; i * i <= n; i += 2) {
      if (n % i === 0) return false;
    }
    return true;
  };

  let count = 0;
  let temp = a;

  for (let i = 2; i * i <= temp; i++) {
    while (temp % i === 0) {
      if (isPrime(i)) {
        count++;
      }
      temp = Math.floor(temp / i);
    }
  }

  if (temp > 1) {
    if (isPrime(temp)) {
      count++;
    }
  }

  return count === 3;
};

